import { GOALS, PACES, type Profile } from "../data/profiles";

/**
 * Match explanations are built from profile facts, never generated by the model.
 * Each line says where it came from, so users can tell stated facts from guesses.
 */
export interface MatchReason {
  /** Things both people actually said. */
  inCommon: string[];
  /** Differences worth knowing about. */
  differences: string[];
  /** What a profile can't tell you. Always shown. */
  unknown: string[];
  sharedInterests: string[];
  sharedValues: string[];
}

function list(items: string[]): string {
  const lower = items.map((i) => i.toLowerCase());
  if (lower.length <= 1) return lower.join("");
  return `${lower.slice(0, -1).join(", ")} and ${lower[lower.length - 1]}`;
}

export function buildMatchReason(me: Profile, them: Profile): MatchReason {
  const sharedInterests = me.interests.filter((i) => them.interests.includes(i));
  const sharedValues = me.values.filter((v) => them.values.includes(v));
  const inCommon: string[] = [];
  const differences: string[] = [];

  if (me.goal === them.goal) {
    inCommon.push(`You're both looking for ${GOALS[me.goal].charAt(0).toLowerCase()}${GOALS[me.goal].slice(1)}.`);
  } else {
    differences.push(`You said "${GOALS[me.goal]}", and ${them.name} said "${GOALS[them.goal]}".`);
  }

  if (sharedInterests.length > 0) {
    inCommon.push(`You both listed ${list(sharedInterests)}.`);
  }

  if (sharedValues.length > 0) {
    inCommon.push(`You both care about ${list(sharedValues)}.`);
  }

  if (me.pace === them.pace) {
    inCommon.push(
      me.pace === "chat-first"
        ? "You both like to chat for a while before meeting."
        : "You'd both rather meet fairly soon than chat for weeks.",
    );
  } else {
    differences.push(
      `You prefer to ${PACES[me.pace].charAt(0).toLowerCase()}${PACES[me.pace].slice(1)}, and ${them.name} prefers to ${PACES[them.pace].charAt(0).toLowerCase()}${PACES[them.pace].slice(1)}.`,
    );
  }

  const unknown = [
    "Whether you click in person.",
    `How ${them.name} communicates day to day.`,
  ];

  return { inCommon, differences, unknown, sharedInterests, sharedValues };
}
